static void sha256_compress_scalar(uint32_t state[8], const uint8_t* block) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++)
        w[i] = ((uint32_t)block[4*i]<<24)|((uint32_t)block[4*i+1]<<16)|((uint32_t)block[4*i+2]<<8)|block[4*i+3];
    for (int i = 16; i < 64; i++) {
        uint32_t s0 = rotr32(w[i-15],7)^rotr32(w[i-15],18)^(w[i-15]>>3);
        uint32_t s1 = rotr32(w[i-2],17)^rotr32(w[i-2],19)^(w[i-2]>>10);
        w[i] = w[i-16]+s0+w[i-7]+s1;
    }
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i = 0; i < 64; i++) {
        uint32_t S1 = rotr32(e,6)^rotr32(e,11)^rotr32(e,25);
        uint32_t ch = (e&f)^(~e&g);
        uint32_t t1 = h+S1+ch+K[i]+w[i];
        uint32_t S0 = rotr32(a,2)^rotr32(a,13)^rotr32(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        uint32_t t2 = S0+maj;
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a;state[1]+=b;state[2]+=c;state[3]+=d;state[4]+=e;state[5]+=f;state[6]+=g;state[7]+=h;
}

void sha256_fast(const uint8_t* data, size_t len, uint8_t* out) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = (len + 9 + 63) / 64;
    uint8_t* buf = malloc(nblocks*64);
    memcpy(buf, data, len);
    buf[len] = 0x80;
    memset(buf+len+1, 0, nblocks*64 - len - 1);
    uint64_t bitlen = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) buf[nblocks*64-8+i] = (bitlen >> (56-8*i)) & 0xff;

    size_t b = 0;
    while (b + 8 <= nblocks) {
        sha256_8blocks_avx2(state, buf + b*64);
        b += 8;
    }
    while (b < nblocks) {
        sha256_compress_scalar(state, buf + b*64);
        b += 1;
    }
    for (int i = 0; i < 8; i++) {
        out[4*i] = (state[i]>>24)&0xff;
        out[4*i+1] = (state[i]>>16)&0xff;
        out[4*i+2] = (state[i]>>8)&0xff;
        out[4*i+3] = state[i]&0xff;
    }
    free(buf);
}

